def transform(g):
    from collections import Counter
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    cells=[(i,j) for i,r in enumerate(g) for j,x in enumerate(r) if x!=bg]
    H,W=len(g),len(g[0])
    o=[r[:] for r in g]
    def fill(i,j):
        if 0<=i<H and 0<=j<W and o[i][j]==bg: o[i][j]=2
    # bounding box border
    r0=min(i for i,j in cells); r1=max(i for i,j in cells)
    c0=min(j for i,j in cells); c1=max(j for i,j in cells)
    for j in range(c0,c1+1): fill(r0,j); fill(r1,j)
    for i in range(r0,r1+1): fill(i,c0); fill(i,c1)
    # gaps of length<=2 between aligned colored cells
    rows={}
    cols={}
    for i,j in cells: rows.setdefault(i,[]).append(j); cols.setdefault(j,[]).append(i)
    for i,js in rows.items():
        js=sorted(js)
        for a,b in zip(js,js[1:]):
            if 1<=b-a-1<=2:
                for j in range(a+1,b): fill(i,j)
    for j,is_ in cols.items():
        is_=sorted(is_)
        for a,b in zip(is_,is_[1:]):
            if 1<=b-a-1<=2:
                for i in range(a+1,b): fill(i,j)
    return o
