def gaps_report(p):
    g,e=p['input'],p['output']
    H,W=len(g),len(g[0])
    bg=max(set(x for r in g for x in r), key=lambda x:sum(r.count(x) for r in g))
    dash=lambda i,j: g[i][j]!=bg
    res=[]
    for i in range(H):
        js=[j for j in range(W) if dash(i,j)]
        for a,b in zip(js,js[1:]):
            if b-a>1:
                filled=all(e[i][j]==2 for j in range(a+1,b))
                res.append(('row',i,a,b,b-a-1,filled))
    for j in range(W):
        is_=[i for i in range(H) if dash(i,j)]
        for a,b in zip(is_,is_[1:]):
            if b-a>1:
                filled=all(e[i][j]==2 for i in range(a+1,b))
                res.append(('col',j,a,b,b-a-1,filled))
    return res
